/* EF Carpet checkout payments (Stripe Elements). Generated by _build/payments.py, do not edit by hand.
 * OFF mode (no real key/endpoint): body.pay-off, card fields are inert boxes, wallets disabled, Place order disabled.
 * ON mode: loads https://js.stripe.com/v3/, mounts cardNumber/cardExpiry/cardCvc into the boxes and the Express Checkout
 * Element (Apple Pay, Google Pay) into #xpay-buttons, asks the endpoint for a PaymentIntent and confirms it with Stripe. */
(function(){
var K=(typeof STRIPE_PUBLISHABLE_KEY=='string')?STRIPE_PUBLISHABLE_KEY:'',EP=(typeof STRIPE_PAYMENT_ENDPOINT=='string')?STRIPE_PAYMENT_ENDPOINT:'';
var READY=/^pk_(live|test)_[A-Za-z0-9]{10,}$/.test(K)&&/^https:\/\/[^{}\s]+$/.test(EP);
window.efcPay={ready:READY};
function $(i){return document.getElementById(i)}
document.addEventListener('DOMContentLoaded',function(){
 var f=$('coform');if(!f)return;
 var po=$('placeorder');
 document.body.classList.add(READY?'pay-on':'pay-off');
 if(!READY){po.disabled=true;po.title='Payments open soon';return}
 if(f.hidden||!efcCart.get().length)return;
 var s=document.createElement('script');s.src='https://js.stripe.com/v3/';s.async=true;
 s.onload=function(){init(f,po)};s.onerror=function(){err('The secure payment fields could not load. Please refresh the page or try again later.')};
 document.head.appendChild(s)});

function err(m){var e=$('card-errors');if(e)e.textContent=m||''}
function val(f,n){var x=f.elements[n];return x?String(x.value||'').trim():''}
function pence(){var E=efcCart,t=0;E.get().forEach(function(i){var it=E.cat[i.h];if(it)t+=Math.round(it.p*100)*i.q});return t}
function abs(p){return new URL(p,location.href).href}

function init(f,po){
 var E=efcCart,stripe=Stripe(K),amount=pence();
 var style={base:{fontFamily:'Inter, "Helvetica Neue", Arial, sans-serif',fontSize:'16px',color:'#17211D','::placeholder':{color:'#8A918C'}},invalid:{color:'#B42318',iconColor:'#B42318'}};
 var els=stripe.elements({locale:'en-GB',fonts:[{cssSrc:'https://fonts.googleapis.com/css2?family=Inter:wght@400;500&display=swap'}]});
 var num=els.create('cardNumber',{style:style,showIcon:true}),exp=els.create('cardExpiry',{style:style}),cvc=els.create('cardCvc',{style:style});
 [['card-number',num],['card-expiry',exp],['card-cvc',cvc]].forEach(function(a){var box=$(a[0]);box.innerHTML='';a[1].mount(box);a[1].on('change',function(ev){err(ev.error?ev.error.message:'')})});
 po.disabled=false;po.removeAttribute('title');

 function customer(){var same=$('samebill').checked;return {email:val(f,'email'),phone:val(f,'phone'),notes:val(f,'notes'),
  shipping:{name:val(f,'first')+' '+val(f,'last'),line1:val(f,'a1'),line2:val(f,'a2'),city:val(f,'town'),county:val(f,'county'),postcode:val(f,'pc').toUpperCase()},
  billing:same?null:{name:val(f,'bfirst')+' '+val(f,'blast'),line1:val(f,'ba1'),city:val(f,'btown'),postcode:val(f,'bpc').toUpperCase()}}}
 function intent(c,method){return fetch(EP,{method:'POST',headers:{'Content-Type':'application/json'},
  body:JSON.stringify({items:E.get().map(function(i){return {h:i.h,q:i.q}}),customer:c,method:method})})
  .then(function(r){return r.json().then(function(j){if(!r.ok||!j.clientSecret)throw new Error(j.error||'We could not start the payment. No money has been taken. Please try again.');
   if(j.amount!==amount)throw new Error('A price in your basket has changed. Please refresh the page to see the current total before paying.');return j})})}
 function done(ref,pi){E.set([]);location.href=abs((E.root||'')+'order-complete.html')+'?ref='+encodeURIComponent(ref)+'&payment_intent='+encodeURIComponent(pi)+'&redirect_status=succeeded'}

 // card payment
 f.onsubmit=function(e){e.preventDefault();err('');
  if(!f.checkValidity()){f.reportValidity();return}
  if($('pcmsg')&&$('pcmsg').className==='warn'){err('We cannot deliver to this postcode. See our Shipping Policy.');return}
  var c=customer(),b=c.billing||c.shipping;po.disabled=true;var lbl=po.textContent;po.textContent='Processing payment...';
  intent(c,'card').then(function(j){return stripe.confirmCardPayment(j.clientSecret,{payment_method:{card:num,billing_details:{name:b.name,email:c.email,phone:c.phone,
    address:{line1:b.line1,line2:b.line2||undefined,city:b.city,postal_code:b.postcode,country:'GB'}}}}).then(function(r){
    if(r.error)throw new Error(r.error.message);if(r.paymentIntent&&(r.paymentIntent.status==='succeeded'||r.paymentIntent.status==='processing'))done(j.orderRef,r.paymentIntent.id);
    else throw new Error('The payment was not completed. No money has been taken.')})})
  .catch(function(x){err(x.message);po.disabled=false;po.textContent=lbl})};

 // express checkout: Apple Pay, then Google Pay (Stripe shows only the wallets this device supports)
 if(!amount)return;
 var xe=stripe.elements({locale:'en-GB',mode:'payment',amount:amount,currency:'gbp',appearance:{variables:{borderRadius:'8px'}}});
 var xp=xe.create('expressCheckout',{paymentMethodOrder:['apple_pay','google_pay'],buttonType:{applePay:'plain',googlePay:'plain'},buttonHeight:46,
  paymentMethods:{applePay:'auto',googlePay:'auto',link:'never',paypal:'never',amazonPay:'never',klarna:'never'},layout:{maxColumns:2,overflow:'never'}});
 var box=$('xpay-buttons');box.innerHTML='';xp.mount(box);
 xp.on('loaderror',function(){$('xpay').hidden=true});
 xp.on('ready',function(ev){var m=ev.availablePaymentMethods;if(!m||(!m.applePay&&!m.googlePay))$('xpay').hidden=true});
 xp.on('click',function(ev){if(!$('terms').checked){err('Please tick the box to agree to the Terms of Service first.');$('terms').focus();return}
  ev.resolve({emailRequired:true,phoneNumberRequired:true,shippingAddressRequired:true,allowedShippingCountries:['GB'],
   shippingRates:[{id:'free-uk',displayName:'Free UK mainland delivery',amount:0}]})});
 xp.on('shippingaddresschange',function(ev){var pc=(ev.address&&ev.address.postal_code||'').toUpperCase().replace(/\s+/g,'');
  if(window.efcExcluded&&window.efcExcluded(pc))ev.reject();else ev.resolve()});
 xp.on('confirm',function(ev){err('');var sa=ev.shippingAddress||{},ad=sa.address||{},bd=ev.billingDetails||{};
  var c={email:bd.email||'',phone:bd.phone||'',notes:'',shipping:{name:sa.name||bd.name||'',line1:ad.line1||'',line2:ad.line2||'',city:ad.city||'',county:ad.state||'',postcode:(ad.postal_code||'').toUpperCase()},billing:null};
  xe.submit().then(function(r){if(r.error)throw new Error(r.error.message);return intent(c,'express')}).then(function(j){
   return stripe.confirmPayment({elements:xe,clientSecret:j.clientSecret,redirect:'if_required',
    confirmParams:{return_url:abs((E.root||'')+'order-complete.html')+'?ref='+encodeURIComponent(j.orderRef)}}).then(function(r){
    if(r.error)throw new Error(r.error.message);done(j.orderRef,r.paymentIntent.id)})})
  .catch(function(x){err(x.message);ev.paymentFailed&&ev.paymentFailed({reason:'fail'})})});
}
})();
